package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;
/** Independent study data. No migration or writes to the file catalogue schema. */
final class StudyStore extends SQLiteOpenHelper {
 final long epoch=WorkspaceEpoch.value;void current(){if(epoch!=WorkspaceEpoch.value||WorkspaceEpoch.restoring)throw new IllegalStateException("A biblioteca está a ser recuperada. Reabra esta janela.");}
 static final String[] TABLES={"courses","subjects","materials","notes","cards","questions","tasks","sessions","quiz_runs","reviews","practice","study_trash"};
 static class Row extends LinkedHashMap<String,String>{String s(String k){String v=get(k);return v==null?"":v;}long n(String k){try{return Long.parseLong(s(k));}catch(Exception e){return 0;}}long id(){return n("id");}}
 StudyStore(Context c){super(c,"seeky-studies.db",null,3);setWriteAheadLoggingEnabled(true);}
 public void onOpen(SQLiteDatabase d){super.onOpen(d);if(!d.isReadOnly()){d.execSQL("CREATE INDEX IF NOT EXISTS materials_shared_file ON materials(hash,path,progress DESC,updated DESC,id)");d.execSQL("CREATE TABLE IF NOT EXISTS material_identity(id INTEGER PRIMARY KEY AUTOINCREMENT)");reserveMaterialIds(d);}}
 static void reserveMaterialIds(SQLiteDatabase d){d.execSQL("INSERT OR IGNORE INTO material_identity(id) SELECT id FROM materials ORDER BY id DESC LIMIT 1");}
 long insertMaterial(ContentValues values){SQLiteDatabase d=getWritableDatabase();boolean own=!d.inTransaction();if(own)d.beginTransaction();try{reserveMaterialIds(d);ContentValues identity=new ContentValues();identity.put("id",(String)null);long id=d.insertOrThrow("material_identity",null,identity);values.put("id",id);d.insertOrThrow("materials",null,values);if(own)d.setTransactionSuccessful();return id;}finally{if(own)d.endTransaction();}}
 public void onCreate(SQLiteDatabase d){
  courseSchema(d);
  d.execSQL("CREATE TABLE subjects(id INTEGER PRIMARY KEY,title TEXT NOT NULL,color INTEGER NOT NULL,created INTEGER NOT NULL,course INTEGER NOT NULL DEFAULT 0,kind TEXT NOT NULL DEFAULT 'subject' CHECK(kind IN ('module','subject'))) ");
  d.execSQL("CREATE INDEX subjects_course ON subjects(course,title)");
  d.execSQL("CREATE TABLE materials(id INTEGER PRIMARY KEY,subject INTEGER NOT NULL DEFAULT 0,title TEXT NOT NULL,author TEXT NOT NULL DEFAULT '',name TEXT NOT NULL,mime TEXT NOT NULL,path TEXT NOT NULL,hash TEXT NOT NULL,bytes INTEGER NOT NULL,progress INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Por estudar',created INTEGER NOT NULL,updated INTEGER NOT NULL,UNIQUE(subject,hash))");
  d.execSQL("CREATE TABLE notes(id INTEGER PRIMARY KEY,subject INTEGER NOT NULL DEFAULT 0,material INTEGER NOT NULL DEFAULT 0,segment INTEGER NOT NULL DEFAULT 0,title TEXT NOT NULL,body TEXT NOT NULL,cues TEXT NOT NULL DEFAULT '',summary TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL,updated INTEGER NOT NULL)");
  d.execSQL("CREATE TABLE cards(id INTEGER PRIMARY KEY,subject INTEGER NOT NULL DEFAULT 0,material INTEGER NOT NULL DEFAULT 0,segment INTEGER NOT NULL DEFAULT 0,front TEXT NOT NULL,back TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '',due INTEGER NOT NULL,interval INTEGER NOT NULL DEFAULT 0,reps INTEGER NOT NULL DEFAULT 0,lapses INTEGER NOT NULL DEFAULT 0,suspended INTEGER NOT NULL DEFAULT 0,updated INTEGER NOT NULL)");
  d.execSQL("CREATE INDEX cards_due ON cards(suspended,due,subject)");
  d.execSQL("CREATE TABLE reviews(id INTEGER PRIMARY KEY,card INTEGER NOT NULL,grade INTEGER NOT NULL,reviewed INTEGER NOT NULL,token TEXT NOT NULL UNIQUE)");
  d.execSQL("CREATE TABLE questions(id INTEGER PRIMARY KEY,subject INTEGER NOT NULL DEFAULT 0,material INTEGER NOT NULL DEFAULT 0,prompt TEXT NOT NULL,answer TEXT NOT NULL,choices TEXT NOT NULL DEFAULT '[]',correct INTEGER NOT NULL DEFAULT -1,explanation TEXT NOT NULL DEFAULT '',kind INTEGER NOT NULL DEFAULT 0,tags TEXT NOT NULL DEFAULT '',updated INTEGER NOT NULL)");
  d.execSQL("CREATE TABLE quiz_runs(id INTEGER PRIMARY KEY,subject INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL,correct INTEGER NOT NULL,self_count INTEGER NOT NULL,created INTEGER NOT NULL,details TEXT NOT NULL)");
  d.execSQL("CREATE TABLE tasks(id INTEGER PRIMARY KEY,subject INTEGER NOT NULL DEFAULT 0,title TEXT NOT NULL,due INTEGER NOT NULL DEFAULT 0,estimate INTEGER NOT NULL DEFAULT 25,priority INTEGER NOT NULL DEFAULT 1,done INTEGER NOT NULL DEFAULT 0,updated INTEGER NOT NULL)");
  d.execSQL("CREATE TABLE sessions(id INTEGER PRIMARY KEY,subject INTEGER NOT NULL DEFAULT 0,started INTEGER NOT NULL,seconds INTEGER NOT NULL,goal TEXT NOT NULL,type TEXT NOT NULL,token TEXT NOT NULL UNIQUE)");
  d.execSQL("CREATE INDEX sessions_date ON sessions(started)");StudyState.schema(d);
 }
 static void courseSchema(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL)");}
 public void onUpgrade(SQLiteDatabase d,int o,int n){if(o<3){courseSchema(d);d.execSQL("ALTER TABLE subjects ADD COLUMN course INTEGER NOT NULL DEFAULT 0");d.execSQL("ALTER TABLE subjects ADD COLUMN kind TEXT NOT NULL DEFAULT 'subject' CHECK(kind IN ('module','subject'))");d.execSQL("CREATE INDEX IF NOT EXISTS subjects_course ON subjects(course,title)");}StudyState.schema(d);}
 static String scope(long course,long subject){String filter=course>0?"subject IN (SELECT id FROM subjects WHERE course="+course+")":"1=1";return subject>0?filter+" AND subject="+subject:filter;}
 void deleteCourse(long id){current();SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{d.update("subjects",values("course",0),"course=?",new String[]{""+id});delete("courses",id);d.setTransactionSuccessful();}finally{d.endTransaction();}}

 List<Row> courses(){List<Row> result=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT c.*, (SELECT COUNT(*) FROM subjects s WHERE s.course=c.id) AS module_count, (SELECT COUNT(*) FROM materials m JOIN subjects s ON s.id=m.subject WHERE s.course=c.id) AS material_count FROM courses c ORDER BY c.title COLLATE NOCASE LIMIT 500",null)){while(c.moveToNext()){Row row=new Row();for(int n=0;n<c.getColumnCount();n++)row.put(c.getColumnName(n),c.getString(n));result.add(row);}}return result;}
 static void table(String t){if(!Arrays.asList(TABLES).contains(t))throw new IllegalArgumentException("Tabela inválida.");}
 List<Row> rows(String table,String where,String[] args,String order,int limit){table(table);List<Row> out=new ArrayList<>();try(Cursor c=getReadableDatabase().query(table,null,where,args,null,null,order,""+Math.max(1,Math.min(10000,limit)))){String[] cols=c.getColumnNames();while(c.moveToNext()){Row r=new Row();for(int i=0;i<cols.length;i++)r.put(cols[i],c.isNull(i)?"":c.getString(i));out.add(r);}}return out;}
 List<Row> page(String table,String where,String[] args,String order,int limit,int offset){table(table);List<Row> out=new ArrayList<>();String window=Math.max(1,Math.min(100,limit))+" OFFSET "+Math.max(0,Math.min(1000000,offset));try(Cursor cursor=getReadableDatabase().query(table,null,where,args,null,null,order,window)){String[] columns=cursor.getColumnNames();while(cursor.moveToNext()){Row row=new Row();for(int n=0;n<columns.length;n++)row.put(columns[n],cursor.isNull(n)?"":cursor.getString(n));out.add(row);}}return out;}

 Row get(String t,long id){List<Row> r=rows(t,"id=?",new String[]{""+id},null,1);return r.isEmpty()?null:r.get(0);}
 static ContentValues values(Object... pairs){ContentValues v=new ContentValues();for(int i=0;i<pairs.length;i+=2){String k=(String)pairs[i];Object x=pairs[i+1];if(x instanceof Integer)v.put(k,(Integer)x);else if(x instanceof Long)v.put(k,(Long)x);else v.put(k,String.valueOf(x));}return v;}
 long save(String t,long id,ContentValues v){current();table(t);if(v.containsKey("subject")&&v.getAsLong("subject")!=0&&get("subjects",v.getAsLong("subject"))==null)throw new IllegalArgumentException("Módulo indisponível.");if(t.equals("subjects")){if(v.containsKey("course")&&v.getAsLong("course")!=0&&get("courses",v.getAsLong("course"))==null)throw new IllegalArgumentException("Curso indisponível.");if(v.containsKey("kind")&&!Arrays.asList("module","subject").contains(v.getAsString("kind")))throw new IllegalArgumentException("Tipo de módulo inválido.");}if(id==0)return t.equals("materials")?insertMaterial(v):getWritableDatabase().insertOrThrow(t,null,v);if(getWritableDatabase().update(t,v,"id=?",new String[]{""+id})!=1)throw new IllegalStateException("Este registo já não existe.");return id;}
 void delete(String t,long id){current();
  table(t);SQLiteDatabase d=getWritableDatabase();boolean own=!d.inTransaction();if(own)d.beginTransaction();
  try{
   if(Arrays.asList("notes","cards","questions","tasks").contains(t)){
    Row row=get(t,id);if(row!=null){org.json.JSONObject payload=new org.json.JSONObject(row);save("study_trash",0,values("table_name",t,"payload",payload.toString(),"deleted",System.currentTimeMillis()));}
   }
   if(t.equals("cards"))d.update("reviews",values("card",0),"card=?",new String[]{""+id});
   d.delete(t,"id=?",new String[]{""+id});if(own)d.setTransactionSuccessful();
  }finally{if(own)d.endTransaction();}
 }
 long count(String t,String where,String[] args){table(t);try(Cursor c=getReadableDatabase().rawQuery("SELECT count(*) FROM "+t+(where==null?"":" WHERE "+where),args)){c.moveToFirst();return c.getLong(0);}}
 void grade(long id,int grade,String token){current();SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{if(count("reviews","token=?",new String[]{token})>0)return;Row card=get("cards",id);if(card==null||card.n("suspended")!=0)throw new IllegalStateException("Cartão indisponível.");long now=System.currentTimeMillis();StudySchedule.Next next=StudySchedule.next(now,(int)card.n("interval"),(int)card.n("reps"),(int)card.n("lapses"),grade);save("cards",id,values("due",next.due,"interval",next.interval,"reps",next.reps,"lapses",next.lapses,"updated",now));save("reviews",0,values("card",id,"grade",grade,"reviewed",now,"token",token));d.setTransactionSuccessful();}finally{d.endTransaction();}}
 void restoreTrash(long id){Row trashed=get("study_trash",id);if(trashed==null)return;String t=trashed.s("table_name");if(!Arrays.asList("notes","cards","questions","tasks").contains(t))throw new IllegalArgumentException("Registo inválido.");SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{org.json.JSONObject o=new org.json.JSONObject(trashed.s("payload"));ContentValues v=new ContentValues();java.util.Set<String> allowed=new java.util.HashSet<>();try(Cursor cols=d.rawQuery("PRAGMA table_info("+t+")",null)){while(cols.moveToNext())allowed.add(cols.getString(1));}java.util.Iterator<String> keys=o.keys();while(keys.hasNext()){String k=keys.next();if(!allowed.contains(k))throw new IllegalArgumentException("Campo de recuperação inválido.");if(!k.equals("id"))v.put(k,o.getString(k));}if(v.containsKey("subject")&&v.getAsLong("subject")>0&&get("subjects",v.getAsLong("subject"))==null)v.put("subject",0);if(v.containsKey("material")&&v.getAsLong("material")>0&&get("materials",v.getAsLong("material"))==null)v.put("material",0);save(t,0,v);d.delete("study_trash","id=?",new String[]{""+id});d.setTransactionSuccessful();}catch(org.json.JSONException e){throw new IllegalStateException(e);}finally{d.endTransaction();}}
 void deleteSubject(long id){current();SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{for(String t:new String[]{"materials","notes","cards","questions","tasks","sessions","quiz_runs"})d.update(t,values("subject",0),"subject=?",new String[]{""+id});delete("subjects",id);d.setTransactionSuccessful();}finally{d.endTransaction();}}
 void removeMaterial(long id){current();SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{reserveMaterialIds(d);for(String t:new String[]{"notes","cards","questions"})d.update(t,values("material",0),"material=?",new String[]{""+id});delete("materials",id);d.setTransactionSuccessful();}finally{d.endTransaction();}}
}
